CREATE TABLE IF NOT EXISTS `vehicles` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `plate` TEXT NOT NULL, `defaultFuelType` TEXT NOT NULL, `tankCapacity` REAL, `initialOdometer` INTEGER NOT NULL, `manualOdometer` INTEGER NOT NULL, `photoVersion` INTEGER NOT NULL, `archived` INTEGER NOT NULL, `distanceUnit` TEXT NOT NULL DEFAULT 'km', `volumeUnit` TEXT NOT NULL DEFAULT 'l', `consumptionFormat` TEXT NOT NULL DEFAULT 'per100', `currency` TEXT NOT NULL DEFAULT '€', `photoThumbPos` TEXT NOT NULL DEFAULT '0,0,1', `photoLargePos` TEXT NOT NULL DEFAULT '0,0,1', `vehicleType` TEXT NOT NULL DEFAULT 'Auto', `updatedAt` INTEGER NOT NULL, `deleted` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `refuels` (`id` TEXT NOT NULL, `vehicleId` TEXT NOT NULL, `timestamp` INTEGER NOT NULL, `odometer` INTEGER NOT NULL, `amount` REAL NOT NULL, `totalPrice` REAL NOT NULL, `fullTank` INTEGER NOT NULL, `missedPrevious` INTEGER NOT NULL, `fuelType` TEXT NOT NULL, `stationBrand` TEXT NOT NULL, `stationAddress` TEXT NOT NULL, `latitude` REAL, `longitude` REAL, `extras` TEXT NOT NULL, `drivingStyle` TEXT NOT NULL, `routeType` TEXT NOT NULL, `tireType` TEXT NOT NULL, `note` TEXT NOT NULL, `updatedAt` INTEGER NOT NULL, `deleted` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `reminders` (`id` TEXT NOT NULL, `vehicleId` TEXT NOT NULL, `title` TEXT NOT NULL, `intervalKm` INTEGER NOT NULL, `lastDoneKm` INTEGER NOT NULL, `warnBeforeKm` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, `deleted` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `services` (`id` TEXT NOT NULL, `vehicleId` TEXT NOT NULL, `timestamp` INTEGER NOT NULL, `odometer` INTEGER NOT NULL, `title` TEXT NOT NULL, `category` TEXT NOT NULL, `cost` REAL NOT NULL, `workshop` TEXT NOT NULL, `note` TEXT NOT NULL, `treadDepth` TEXT NOT NULL DEFAULT '', `tireSeason` TEXT NOT NULL DEFAULT '', `tireBrand` TEXT NOT NULL DEFAULT '', `tireModel` TEXT NOT NULL DEFAULT '', `tireSize` TEXT NOT NULL DEFAULT '', `tireSetId` TEXT NOT NULL DEFAULT '', `removedTireSetId` TEXT NOT NULL DEFAULT '', `updatedAt` INTEGER NOT NULL, `deleted` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `tire_sets` (`id` TEXT NOT NULL, `vehicleId` TEXT NOT NULL, `season` TEXT NOT NULL, `brandFront` TEXT NOT NULL, `modelFront` TEXT NOT NULL, `sizeFront` TEXT NOT NULL, `brandRear` TEXT NOT NULL, `modelRear` TEXT NOT NULL, `sizeRear` TEXT NOT NULL, `note` TEXT NOT NULL, `updatedAt` INTEGER NOT NULL, `deleted` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_refuels_vehicleId` ON `refuels` (`vehicleId`);
CREATE INDEX IF NOT EXISTS `index_reminders_vehicleId` ON `reminders` (`vehicleId`);
CREATE INDEX IF NOT EXISTS `index_services_vehicleId` ON `services` (`vehicleId`);
CREATE INDEX IF NOT EXISTS `index_tire_sets_vehicleId` ON `tire_sets` (`vehicleId`);
